<span class="script">Awards</span><h2 class="text-4xl mb-6">Sertifikat &amp; Prestasi</h2><div class="grid md:grid-cols-3 gap-5">
<?php $rows=all('SELECT id,title,year,description,image FROM certificates ORDER BY id DESC');foreach($rows as $c):?><div class="card"><?php if($c['image']):?><button type="button" class="block w-full mb-2 cursor-zoom-in" data-zoom="<?=img($c['image'])?>" aria-label="Perbesar sertifikat"><img src="<?=img($c['image'])?>" class="w-full aspect-[1280/886] object-cover border" loading="lazy" decoding="async" width="1280" height="886" alt="Sertifikat <?=e($c['title'])?>"></button><?php endif?><h3 class="text-base"><?=e($c['title'])?></h3><p class="text-sm"><?=e($c['year'])?> — <?=e($c['description'])?></p></div><?php endforeach; if(!$rows)echo '<p>Belum ada data.</p>';?></div>
<dialog id="zm" class="p-0 bg-transparent max-w-[95vw] backdrop:bg-black/80"><form method="dialog"><button class="btn btn-p absolute right-2 top-2" aria-label="Tutup">✕</button></form><img id="zi" class="max-h-[90vh] max-w-[95vw]" alt=""></dialog>
<script>const zm=document.getElementById('zm'),zi=document.getElementById('zi');document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{zi.src=b.dataset.zoom;zm.showModal()});zm.onclick=e=>{if(e.target===zm)zm.close()}</script>
